# -*- coding: utf-8 -*-
# 第 101-125 课内容数据
LESSONS_PART = [

# ============ 第7章 物理系统 (101-110) ============
{"num":101,"title":"射线检测进阶：图层过滤与命中信息","summary":"掌握 Raycast 的完整参数：距离、LayerMask、命中点/法线/距离的运用。","keywords":"raycast进阶,图层过滤,layermask,命中信息,raycasthit,法线","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 LayerMask 过滤","掌握 RaycastHit 详细信息","掌握多条射线与数组查询"],
 "intro":"上节课学会了基本射线，本课把它的“全身功能”挖掘出来：只打指定层、读取命中点与法线。",
 "sections":[
  {"h":"Raycast 完整参数","lead":"一行代码看全部能力。",
   "steps":["完整语法：Physics.Raycast(origin, direction, out hit, maxDistance, layerMask, queryTriggerInteraction);","参数逐一说明：","① origin 起点（Vector3）","② direction 方向（单位向量）","③ out hit 命中信息（RaycastHit）","④ maxDistance 最大检测距离","⑤ layerMask 只检测的层（位掩码，第 99 课）","⑥ queryTriggerInteraction：是否检测触发器（Ignore/Query/Collide）","【简写】多数情况只需前 4 个参数。","【返回多个】Physics.RaycastAll(ray, distance) 返回所有被射中的物体数组（穿过多个）。","【最近与最远】RaycastAll 后按 hit.distance 排序即可。","【球形射线】Physics.SphereCast：带“粗细”的射线（有半径），更真实。","【性能】每条射线是一次物理查询，避免每帧成千上万条。"],
   "tips":[{"t":"note","c":"射线默认不检测触发器（勾了 Is Trigger 的），需要时用第 6 个参数开启。"}]},
  {"h":"RaycastHit 命中信息实战","lead":"用命中点与法线做特效。",
   "steps":["新建脚本 RayAdvDemo：","if (Physics.Raycast(transform.position, transform.forward, out RaycastHit hit, 10f)) {","Debug.Log(\"名字：\" + hit.collider.name);","Debug.Log(\"命中点：\" + hit.point);","Debug.Log(\"法线：\" + hit.normal);","Debug.Log(\"距离：\" + hit.distance);","Debug.Log(\"刚体：\" + hit.rigidbody);","Debug.DrawLine(transform.position, hit.point, Color.green); // 画线到命中点","}","【命中点 hit.point】在击中位置生成特效：Instantiate(effectPrefab, hit.point, Quaternion.LookRotation(hit.normal));","【法线 hit.normal】让特效“贴”在被击表面（垂直方向）。","【距离 hit.distance】判断远近做伤害衰减。","【刚体 hit.rigidbody】对被击中物体施加力：hit.rigidbody.AddForce(...)。","【常用组合】射击命中：命中点生成火花 + 对被击刚体加力 + 扣血。"],
   "tips":[{"t":"success","c":"RaycastHit 三宝：hit.point（在哪）、hit.normal（朝向）、hit.rigidbody（打的是谁）。"}]},
 ],
 "errors":[{"err":"射线穿过物体却没检测到？","why":"LayerMask 未包含该层，或对象是触发器","fix":"检查 LayerMask；用 queryTriggerInteraction 开启触发器检测。"}],
 "exercise":["用 RaycastAll 返回所有命中物体","在命中点生成一个小特效","对被击中的刚体施加 Impulse 力"],
 "summary":"射线进阶已掌握。下一课学物理查询与抛体运动。"},

{"num":102,"title":"物理查询与抛体运动","summary":"掌握 OverlapSphere 等物理查询，实现范围检测；理解并实现抛物线。","keywords":"overlapsphere,范围检测,物理查询,抛体运动,抛物线,弹道","time":"约 15 分钟","difficulty":"入门",
 "objectives":["掌握物理查询方法","实现范围检测","实现抛物线发射"],
 "intro":"“周围有没有敌人？”用物理查询（OverlapSphere）扫一圈；“炮弹飞行的弧线”是抛体运动。本课两个硬核主题。",
 "sections":[
  {"h":"物理查询 Overlap 系列","lead":"检测“范围内的所有物体”。",
   "steps":["【OverlapSphere】检测球形范围内的所有碰撞体：","Collider[] hits = Physics.OverlapSphere(center, radius, layerMask);","返回一个碰撞体数组；空数组 = 范围内无物体。","【常用】炸弹爆炸范围内是否有敌人、主角周围是否有敌人进入。","【变体】OverlapBox（盒形）、OverlapCapsule（胶囊）。","【射线查询】SphereCast 带半径的射线。","【实战】地雷：OnTriggerEnter 引爆后，OverlapSphere 半径 5 内所有带 Enemy 标签的对象扣血。","【可视化】用 Gizmos.DrawWireSphere 在编辑器里画出检测范围（调试）。","【性能】OverlapSphere 较快，但仍避免每帧多次调用（可定时/事件触发）。"],
   "tips":[{"t":"note","c":"Gizmos.DrawWireSphere 是调试范围检测的利器，开发时画出范围防“看不见的 bug”。"}]},
  {"h":"抛体运动（抛物线）","lead":"让炮弹沿弧线飞行。",
   "steps":["【概念】抛体 = 有初速度 + 受重力，轨迹是抛物线。","【方式1 物理法】给炮弹刚体 + 一个初速度（AddForce/velocity），重力自动画弧：","rb.velocity = 方向 * 初速; // 然后受重力自然下落成抛物线","【方式2 计算法】用抛物线公式：Vector3 pos = start + dir * t * speed + Vector3.down * 0.5f * gravity * t * t;","【取命中】射线预测落点、检测着地（第 101 课技巧）。","【弹道预测】用数学算出落点：t 满足 y 回到地面高度。","【实战】做一个“大炮”：炮口方向 + 固定初速，炮弹刚体发射，观察弧线。","【调参】初速越大弧越平，重力越大弧越陡。","【用途】投石车、手雷、篮球、炮弹。"],
   "tips":[{"t":"note","c":"物理法（刚体+velocity）最简单，多数游戏够用；计算法用于“精确预测落点”（AI 瞄准）。"}]},
 ],
 "errors":[{"err":"抛物线看起来不对？","why":"初速方向或重力设置不当","fix":"确认 velocity 方向是“斜上方”而非纯水平；Use Gravity 保持勾选。"}],
 "exercise":["用 OverlapSphere 检测 3 米内的敌人","做一个带弧线的手雷（刚体+初速）","用 Gizmos 画出检测范围"],
 "summary":"物理查询与抛体已掌握。下一课学拖拽物体。"},

{"num":103,"title":"拖拽物体（鼠标拖拽 3D 物体）","summary":"实现用鼠标拖起、移动、放下 3D 物体，掌握射线+物理的配合。","keywords":"拖拽,drag,鼠标拖拽,拾起,放下,物理拖拽","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现射线拾取","实现拖拽移动","实现放下物体"],
 "intro":"“把箱子拖到机关上”是很多解谜/建造游戏的玩法。本课用射线 + 物理实现完整拖拽。",
 "sections":[
  {"h":"拖拽原理","lead":"三步走。",
   "steps":["【拾取】鼠标按下时，从屏幕发射射线（第 100 课），命中带“可拖拽”标签/脚本的对象。","【拖起】让对象跟随鼠标移动（射线打在某个平面上，对象移动到命中点）。","【放下】鼠标松开时，停止跟随并保持物理状态。","【关键点】射线要打在“拖拽平面”（如地面 Plane）或使用“深度固定”。","【坐标转换】把鼠标屏幕坐标转成世界坐标。","【实现选择】简单版用直接改 Transform；物理版用刚体 velocity 或 MovePosition 更真实。","【标签】给可拖拽物体加 Tag “Draggable” 或专用脚本标记。"],
   "tips":[{"t":"note","c":"本课是“射线 + 坐标转换 + 物理”的综合运用，逻辑简单但细节多。"}]},
  {"h":"实现拖拽","lead":"完整代码。",
   "steps":["新建脚本 DragObject 挂到可拖拽物体上：","private bool isDragging = false;","private float distance = 5f;","void OnMouseDown() { isDragging = true; }","void OnMouseUp() { isDragging = false; }","void Update() { if (isDragging) { Vector3 mouse = Input.mousePosition; mouse.z = distance; // 到相机的深度","Vector3 worldPos = Camera.main.ScreenToWorldPoint(mouse);","transform.position = Vector3.Lerp(transform.position, worldPos, 0.3f); // 平滑跟随 } }","【说明】OnMouseDown/Up 是 Unity 内置的“鼠标点中本物体”回调，前提：对象有碰撞体 + 有相机脚本。","保存播放：鼠标按住物体拖动，松开放下。","【物理版】给物体加刚体，改用 rb.MovePosition(worldPos) 更平滑。","【限制】一次拖一个：拖起时禁用其他物体拖拽（管理器控制）。","【放置判断】放下时检测是否在“目标区域”（触发器）内，触发机关。"],
   "tips":[{"t":"success","c":"OnMouseDown/Up 是最简单的拖拽入口；复杂需求再用射线+UI 事件（第 166 课）。"}]},
 ],
 "errors":[{"err":"OnMouseDown 不触发？","why":"对象无碰撞体，或相机没有挂可执行脚本，或物体被 UI 遮挡","fix":"确认有碰撞体；确认 Main Camera 存在；UI 遮挡时改用射线方案。"}],
 "exercise":["实现基本拖拽（Transform 跟随）","给物体加刚体实现物理拖拽","拖到指定触发器区域触发事件"],
 "summary":"拖拽已实现。下一课学爆炸与冲击力。"},

{"num":104,"title":"爆炸与冲击力","summary":"用 AddExplosionForce 实现爆炸：范围伤害、冲击波、把物体炸飞。","keywords":"爆炸,explosion,addexplosionforce,冲击波,范围伤害","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握 AddExplosionForce","实现范围冲击","结合伤害系统"],
 "intro":"炸弹爆炸要有视觉冲击：范围内物体被炸飞、扣血、冒烟。本课实现物理冲击。",
 "sections":[
  {"h":"AddExplosionForce 基础","lead":"Unity 内置的爆炸力。",
   "steps":["语法：rb.AddExplosionForce(power, 爆炸中心, 半径, 上升力, ForceMode);","参数：power（力量）、explosionPosition（爆炸中心点）、radius（影响半径）、upwardsModifier（向上加成）、mode（默认 Impulse）。","只对“带刚体且在半径内”的物体生效。","【作用】半径内刚体被“炸开”，距离越近力量越大（线性衰减）。","【upwardsModifier】让物体被炸得“向上飞”而不是纯水平飞。","【调用位置】在爆炸逻辑处调用（每帧一次或触发时一次）。","【注意】需要遍历半径内所有刚体，配合 OverlapSphere（第 102 课）。"],
   "tips":[{"t":"note","c":"AddExplosionForce 自动按距离衰减，一个调用解决“爆炸冲击”。"}]},
  {"h":"实战：完整爆炸","lead":"爆炸 = 冲击 + 伤害 + 特效。",
   "steps":["创建脚本 Explosion，挂到炸弹/手雷上：","public float radius = 5f; public float power = 500f; public float damage = 50f;","void Explode() {","Vector3 center = transform.position;","Collider[] cols = Physics.OverlapSphere(center, radius);","foreach (Collider c in cols) {","Rigidbody rb = c.attachedRigidbody;","if (rb != null) { rb.AddExplosionForce(power, center, radius, 3f); }","IDamageable d = c.GetComponent<IDamageable>(); if (d != null) { d.TakeDamage(damage); }","}","Instantiate(effectPrefab, center, Quaternion.identity); // 爆炸特效","Destroy(gameObject); // 炸弹消失","}","【触发】在 OnTriggerEnter 里调用 Explode()（引信），或延时协程。","【特效】把粒子爆炸特效做成预制体（第 191 课）。","【伤害】用 IDamageable 接口（第 68 课）让所有可受伤对象响应。","【注意】特效预制体要延迟销毁，避免永久残留。"],
   "tips":[{"t":"success","c":"爆炸公式 = OverlapSphere 找目标 + AddExplosionForce 冲击 + 接口伤害 + 特效预制体。"}]},
 ],
 "errors":[{"err":"物体没被炸飞？","why":"物体无刚体，或 power 太小，或半径不对","fix":"确认目标带刚体；调大 power（如 800）；确认 radius 覆盖目标。"}],
 "exercise":["实现带冲击的爆炸","用接口让敌人被爆炸扣血","在爆炸点生成粒子特效"],
 "summary":"爆炸已实现。下一课学重力调节与自定义重力。"},

{"num":105,"title":"重力调节与自定义重力","summary":"掌握全局重力设置与局部重力模拟，实现月球漫步、太空漂浮等效果。","keywords":"重力,gravity,自定义重力,月球,漂浮,force","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握全局重力设置","实现局部重力模拟","理解重力实现原理"],
 "intro":"“月球上跳得高”“太空漂浮”“反转重力”——本课玩转重力。",
 "sections":[
  {"h":"全局重力设置","lead":"改整个世界的地心引力。",
   "steps":["菜单 Edit → Project Settings → Physics → 找到【Gravity】。","默认是 (0, -9.81, 0)：向下 9.81 米/秒²。","改成 (0, -1, 0)：重力变弱（月球感）；改成 (0, 9.81, 0)：重力向上！","改小重力：物体下落更慢、跳跃更高。","【注意】全局重力影响所有带 Use Gravity 的刚体。","【固定步长】物理模拟与 Fixed Timestep 有关，改重力后物理行为同步变化。","【建议】一般保持默认，特殊关卡再临时改（用代码恢复）。"],
   "tips":[{"t":"note","c":"重力方向可以为任意向量，做“反转关卡”就把它改成朝上。"}]},
  {"h":"自定义重力（局部）","lead":"给单个物体“定制引力”。",
   "steps":["方式1：关闭刚体 Use Gravity，自己在 FixedUpdate 里施加恒力模拟：","void FixedUpdate() { rb.AddForce(Vector3.up * localGravity, ForceMode.Acceleration); }","localGravity 可正可负，实现“此物向上飘/向下坠”。","方式2：施加“向某个中心点”的引力（星球引力）：","Vector3 dir = (center - rb.position).normalized; rb.AddForce(dir * gravity, ForceMode.Acceleration);","【月球漫步】全局重力改 (0,-2,0) + 跳高力调大，体验失重跳跃。","【太空漂浮】关闭 Use Gravity，用 AddForce 微操。","【注意】自定义重力时不要勾 Use Gravity，否则叠加。","【应用】行星引力、磁力场、局部重力平台。"],
   "tips":[{"t":"success","c":"记住：全局重力在 Project Settings；局部重力=关 Use Gravity + 自己 AddForce。"}]},
 ],
 "errors":[{"err":"物体上下乱飘？","why":"Use Gravity 与自定义力叠加","fix":"关闭 Use Gravity 只用自定义力；或反之，别两个都开。"}],
 "exercise":["把全局重力改小体验月球跳跃（记得改回）","给一个物体实现“向上飘”的自定义重力","实现朝某个中心点的引力"],
 "summary":"重力调节已掌握。下一课学移动平台与传送带。"},

{"num":106,"title":"移动平台与传送带","summary":"实现移动平台（乘客系统）与传送带，让玩家站在上面一起移动。","keywords":"移动平台,传送带,电梯,平台移动,乘客,kinematic","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现移动平台","实现传送带","实现“站在上面跟着走”"],
 "intro":"“站上电梯一起升”是 3D 游戏常见关卡元素。本课实现移动平台与传送带。",
 "sections":[
  {"h":"移动平台","lead":"让平台来回/上下移动。",
   "steps":["创建平台：Cube 拉长拉扁，命名为 Platform。","给平台加 Rigidbody，勾选【Is Kinematic】（运动学：由代码移动，不影响物理碰撞但会推人）。","新建脚本 MovingPlatform 挂到平台：","public Vector3 offset = new Vector3(4, 0, 0); public float speed = 2f;","private Vector3 startPos;","void Start() { startPos = transform.position; }","void Update() { transform.position = startPos + offset * Mathf.Sin(Time.time * speed); }","【Mathf.Sin】正弦波让平台来回平滑移动（值在 -1 到 1 之间循环）。","播放：平台来回滑动。","【“乘客”效果】玩家站在平台上会跟着平台一起走吗？需要“玩家平台检测”（下一步）。"],
   "tips":[{"t":"note","c":"Is Kinematic 平台 + 移动 = 能推人走的基础；但它不会“自动带走”站立者，需乘客系统。"}]},
  {"h":"乘客系统与传送带","lead":"让玩家被平台“带着走”。",
   "steps":["【乘客系统】在玩家脚本里检测脚下是否有移动平台：","void OnCollisionEnter(Collision c) { if (c.gameObject.CompareTag(\"Platform\")) { platform = c.transform; } }","void OnCollisionExit(Collision c) { if (c.gameObject.CompareTag(\"Platform\")) { platform = null; } }","Update 里：if (platform != null) { transform.position += platform.position - platformLastPos; } 记录平台上一帧位置，把差值叠加给玩家。","【传送带】给平面加刚体（Kinematic）+ 碰撞体，写脚本：","void OnCollisionStay(Collision c) { Rigidbody rb = c.rigidbody; if (rb != null) { rb.AddForce(Vector3.right * force); } }","或直接对站立者施加“传送带方向”的力。","【更稳方案】用 CharacterController.Move 的角色可用平台速度辅助（进阶）。","【注意】平台与玩家都要有碰撞体，平台 Kinematic。","【验证】让玩家站上平台，观察是否被带着移动。"],
   "tips":[{"t":"warn","c":"乘客系统的关键是“记录平台每帧位移并叠加给玩家”，忘了记录就完全失效。"}]},
 ],
 "errors":[{"err":"玩家站在平台上会抖动/穿透？","why":"玩家或平台物理配置冲突","fix":"平台用 Is Kinematic；玩家用刚体且 Collision Detection 调 Continuous；差值叠加要乘 deltaTime 的由平台速度驱动。"}],
 "exercise":["做一个来回移动的平台","让玩家站在上面被带着走","实现一条把物体推走的传送带"],
 "summary":"移动平台与传送带已实现。下一课学物体跟随与注视。"},

{"num":107,"title":"物体跟随与注视（Follow & LookAt）","summary":"掌握物体的跟随、注视、平滑插值，实现追踪与瞄准效果。","keywords":"跟随,follow,lookat,注视,插值,lerp,slerp,smoothfollow","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现物体跟随","实现平滑跟随","实现注视目标"],
 "intro":"“相机跟着主角”“无人机盯着敌人”——本课实现跟随与注视这两大基础行为。",
 "sections":[
  {"h":"跟随目标","lead":"让 A 跟着 B。",
   "steps":["【硬跟随】每帧把位置设为目标位置：transform.position = target.position;（会瞬移、抖动）。","【平滑跟随】用 Lerp 插值：transform.position = Vector3.Lerp(transform.position, target.position, speed * Time.deltaTime);","speed 越大跟得越紧，越小越“迟钝”。","【保持偏移】相机通常跟在主角“后上方”：transform.position = Vector3.Lerp(transform.position, target.position + offset, speed * Time.deltaTime);","offset 如 new Vector3(0, 2, -4)（主角后上方 4 米）。","【匀速跟随】用 MoveTowards：transform.position = Vector3.MoveTowards(transform.position, target.position, speed * Time.deltaTime); 匀速不拖尾。","【延迟跟随】记录一个队列实现“蛇形跟随”（进阶）。"],
   "tips":[{"t":"note","c":"Lerp 适合“软跟”（相机、追踪弹），MoveTowards 适合“硬跟”（敌人追击）。"}]},
  {"h":"注视目标","lead":"让 A 面向 B。",
   "steps":["【直接注视】transform.LookAt(target); 让对象正面（Z 轴）朝向目标。","【平滑注视】用 Slerp 插值旋转：","Quaternion targetRot = Quaternion.LookRotation(target.position - transform.position);","transform.rotation = Quaternion.Slerp(transform.rotation, targetRot, speed * Time.deltaTime);","【只水平注视】（角色只转身体不抬头）：把目标位置的 Y 改成与自己相同再 LookAt。","【面向移动方向】移动时先 LookAt 移动方向。","【相机注视】相机看向玩家：camera.LookAt(player)。","【应用】炮塔瞄准、怪物面向玩家、相机跟随、无人机。","【注意】LookAt 会立即旋转；平滑版用 Slerp 过渡。"],
   "tips":[{"t":"success","c":"组合拳：LookRotation（算朝向）+ Slerp（平滑旋转）是“转身动画”级的基础。"}]},
 ],
 "errors":[{"err":"跟随物体抖动？","why":"直接用 position 硬跟或插值过快","fix":"插值放 LateUpdate（第 71 课，相机用 LateUpdate 在角色移动后更新）；降低速度。"}],
 "exercise":["实现相机平滑跟随主角（带偏移）","实现一个始终看向玩家的炮塔","实现敌人追击玩家（跟随+注视）"],
 "summary":"跟随与注视已掌握。下一课深入摩擦与弹性应用。"},

{"num":108,"title":"摩擦与弹性的实际应用","summary":"用物理材质做出冰面、沙地、弹床等真实表面，掌握常见组合。","keywords":"摩擦,弹性,物理材质应用,冰面,弹床,沙地","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握常见表面材质参数","做出冰面/沙地/弹床","理解摩擦系数的配合"],
 "intro":"把第 93 课的物理材质用出花样：冰面滑行、沙地减速、弹床弹人。本课给常见表面配“标准配方”。",
 "sections":[
  {"h":"常见表面配方","lead":"直接抄参数。",
   "steps":["【冰面 Ice】Dynamic Friction=0、Static Friction=0、Bounciness=0：角色走上去打滑，球滑得远。","【沙地/地毯 Sand】Friction=1、Bounciness=0：强烈减速，球很快停下。","【木地板 Wood】Friction=0.4、Bounciness=0.2：适中手感。","【橡胶球 Rubber】Friction=0.6、Bounciness=0.7：弹且有抓地。","【弹床 Trampoline】Bounciness=1（或更大）、Friction=0.3：踩上去被高高弹起。","【滑梯 Slide】Friction=0、Bounciness=0 + 倾斜表面：角色滑下去。","【金属 Metal】Friction=0.3、Bounciness=0.5。","记住“摩擦越小越滑、弹性越大越弹”，按需组合。"],
   "tips":[{"t":"note","c":"配方不是绝对，实际以你的手感为准，先按配方起步再微调。"}]},
  {"h":"组合实现一个“滑冰场+弹床”","lead":"动手验证配方。",
   "steps":["创建三块相邻的地板（Cube 压扁），分别赋上 Ice、Sand、Rubber 三种物理材质。","做一个球（Sphere + 刚体），从一端以相同初速度推出（AddForce Impulse）。","观察球在三块地上的表现：冰上滑得最远、沙地最快停下、橡胶有反弹。","再做一块“弹床”：把 Rubber 材质 Bounciness 调到 1，让角色/球踩上去弹起。","【角色滑冰】给角色（带刚体）加一个“加速/减速”逻辑：在冰面上按方向键获得初速度后不再施力（惯性滑行）。","【对比实验】每块地板都放一个球同时释放，直观对比。","【注意】物理材质赋给 Collider 的 Material 槽，别赋错。","【调优】Bounciness 超 1 会越弹越高，注意控制。"],
   "tips":[{"t":"success","c":"三块地板对比实验做完，你对摩擦/弹性的理解就实战化了。"}]},
 ],
 "errors":[{"err":"角色在冰面上反而“原地踏步”？","why":"角色每帧都在施加移动力，抵消了滑行感","fix":"让角色“先给初速、松键后不再施力”，才能体现惯性滑行。"}],
 "exercise":["制作冰/沙/橡胶三块地板并对比测试","做一个弹床让球高高弹起","调整参数直到手感满意"],
 "summary":"摩擦与弹性应用已掌握。下一课学刚体插值 Interpolation。"},

{"num":109,"title":"刚体插值 Interpolation 与抖动消除","summary":"解决物理物体画面抖动：理解刚体 Interpolation 与物理帧率的关系。","keywords":"interpolation,插值,抖动,extrapolate,刚体平滑","time":"约 11 分钟","difficulty":"入门",
 "objectives":["理解抖动的成因","掌握 Interpolation 设置","解决相机/物理抖动"],
 "intro":"刚体明明匀速移动，画面却一顿一顿？这是物理帧率与渲染帧率不同步导致的。本课用 Interpolation 解决。",
 "sections":[
  {"h":"为什么会抖","lead":"物理与渲染的“时差”。",
   "steps":["物理在 FixedUpdate（固定步长）里计算，比如每秒 50 次。","渲染在 Update/渲染帧里进行，可能每秒 60 次或更高。","当两者频率不一致时，物理物体的渲染位置可能“跳变”，看起来抖动/卡顿。","【内插 Interpolate】在两次物理计算之间“补”出平滑的渲染位置：物理 50 次 → 渲染 60 帧，用插值补齐中间位置。","【外插 Extrapolate】根据当前速度“外推”下一帧位置（帧率低于物理时用）。","【设置位置】刚体组件 → Interpolate 下拉：None（默认）、Interpolate（内插）、Extrapolate（外插）。"],
   "tips":[{"t":"note","c":"绝大多数情况把刚体 Interpolate 设为 Interpolate 即可，肉眼可见地更顺滑。"}]},
  {"h":"实战设置与验证","lead":"设置并观察对比。",
   "steps":["做一个匀速移动的刚体球（velocity 恒定）。","播放观察移动：可能看到轻微抖动（尤其帧率不稳定时）。","暂停，选中球，把 Rigidbody 的 Interpolate 改为 Interpolate。","再次播放对比：移动明显更顺滑。","【相机场景】如果相机跟随刚体物体（第 107 课）仍有抖动，把被跟随刚体的 Interpolate 打开。","【镜头抖动】还可用 Cinemachine 或相机 LateUpdate 平滑（第 247 课）。","【注意】Extrapolate 通常不如 Interpolate 稳定，除非特殊需求。","【配合】Fixed Timestep 越密物理越稳但越耗；Interpolate 是“免费”的平滑。"],
   "tips":[{"t":"success","c":"看到刚体抖动先想到 Interpolate，90% 的抖动问题一秒解决。"}]},
 ],
 "errors":[{"err":"设置了 Interpolate 还是抖？","why":"可能是相机跟随本身抖，或 Fixed Timestep 太大","fix":"相机用 LateUpdate + 平滑；把 Fixed Timestep 调小（如 0.01）；检查是否直接改 transform 绕过物理。"}],
 "exercise":["做一个匀速刚体球对比 Interpolate 前后效果","把相机的跟随也放到 LateUpdate","总结抖动的主要原因与解法"],
 "summary":"刚体插值已掌握。下一课综合练习：打砖块物理小游戏。"},

{"num":110,"title":"综合练习：打砖块物理小游戏","summary":"综合运用刚体、碰撞、触发、物理材质、射击，做一个完整物理小游戏。","keywords":"综合练习,打砖块,breakout,物理游戏,刚体,碰撞","time":"约 30 分钟","difficulty":"入门",
 "objectives":["综合运用第 7 章全部知识","独立完成物理小游戏","体验完整项目流程"],
 "intro":"把物理知识做成一个能玩的小游戏：移动挡板、发射球、弹回、消除砖块。这是物理章的毕业项目！",
 "sections":[
  {"h":"搭建场景","lead":"挡板 + 球 + 砖块墙。",
   "steps":["新建场景 Breakout。","【挡板】Cube 压扁拉长（Scale (2,0.3,0.3)），位置 (0,0.3,0)，命名 Paddle。","给挡板加 Rigidbody，勾选 Is Kinematic（由代码控制）、冻结部分轴。","【球】Sphere（Scale 0.3），命名 Ball，位置 (0,0.8,0)，加 Rigidbody（设速度时用）。","【砖块】Cube 小方块（Scale (0.8,0.3,0.3)），做成不同颜色的预制体 BrickRed、BrickBlue。","用 for 循环脚本或手动摆放 3 排砖块（第 53 课批量生成技巧）。","【相机】Main Camera 摆在球前方上方，俯视整个区域。"],
   "tips":[{"t":"note","c":"物理游戏先摆好“舞台”，再写脚本。"}]},
  {"h":"编写逻辑","lead":"挡板控制 + 球物理 + 消除砖块。",
   "steps":["【挡板控制脚本 PaddleControl】：","float h = Input.GetAxis(\"Horizontal\");","transform.Translate(h * speed * Time.deltaTime, 0, 0);","（限制在左右边界内：Mathf.Clamp）。","【球的发射与反弹】给球加刚体，空格发射：","rb.velocity = new Vector3(3, 5, 0); // 斜上方初速","球碰到挡板/墙/砖块自动反弹（物理碰撞默认）。","【砖块脚本 Brick】：","void OnCollisionEnter(Collision c) { if (c.gameObject.CompareTag(\"Ball\")) { Destroy(gameObject); } }","给球加 Tag “Ball”。","【防止球一直斜飞】让球每次碰撞后速度方向合理（用物理材质 Bounciness=1 保持能量）。","【失败/胜利】球掉出屏幕（y < -5）则失败重置；砖块清空则胜利。","【显示】用 UI 显示得分（第 10 章）。"],
   "tips":[{"t":"success","c":"这个游戏用到：刚体、碰撞事件、预制体、Tag、物理材质、Input、Destroy——物理章全复习了。"}]},
  {"h":"收尾","lead":"打磨与保存。",
   "steps":["给球加物理材质（Bounciness=1）让反弹更稳定。","给砖块加不同颜色增加视觉。","加背景音乐与击中音效（第 11 章音频，先可跳过）。","加“砖块全部消除 → 胜利”的判定与 UI 提示。","检查 Console 无报错，保存。","把完成的游戏展示给朋友玩！","【延伸】加入关卡、特殊砖块（两下才碎）、道具掉落（第 58 课 List 管理）。"],
   "tips":[{"t":"note","c":"完成一个小游戏 = 完整的成就。物理章到此结束，下一章进入输入系统。"}]},
 ],
 "errors":[{"err":"球越飞越快/越慢？","why":"能量不守恒（摩擦或碰撞损耗）","fix":"给球物理材质 Bounciness=1、Friction=0；必要时用代码保持恒定速率：rb.velocity = rb.velocity.normalized * speed;"}],
 "exercise":["完成打砖块游戏的基本玩法","加入得分与胜负判定","（进阶）加道具掉落与多关卡"],
 "summary":"打砖块完成！物理章毕业。下一章进入输入系统，让玩家“操控”游戏。"},

# ============ 第8章 输入系统 (111-125) ============
{"num":111,"title":"Input.GetAxis 轴向输入","summary":"掌握 Input.GetAxis 平滑输入：WASD/方向键控制移动与相机。","keywords":"input.getaxis,轴向输入,wasd,方向键,平滑输入,horizontal","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 GetAxis 输入值","掌握水平/垂直轴","实现平滑移动"],
 "intro":"GetAxis 返回“平滑的 -1 到 1 数值”，是控制移动的标准方式。本课彻底搞懂它。",
 "sections":[
  {"h":"Input.GetAxis 基础","lead":"“轴”就是一组按键的“虚拟摇杆”。",
   "steps":["【Horizontal 水平轴】Input.GetAxis(\"Horizontal\")：按 A/← 返回趋近 -1，按 D/→ 返回趋近 1，不按返回 0。","【Vertical 垂直轴】Input.GetAxis(\"Vertical\")：按 W/↑ 返回 +1，按 S/↓ 返回 -1。","【平滑】GetAxis 是“逐渐变化”的（有加速度），不会瞬间跳到 1，手感柔和。","【映射配置】Edit → Project Settings → Input Manager：能看到每个轴的按键映射（可自定义）。","【用法】float h = Input.GetAxis(\"Horizontal\");","【组合移动】new Vector3(h, 0, v) 得到二维输入方向。","【注意】GetAxis 的 0 表示“无输入”，不会误判为按键按下。","【兄弟方法】GetAxisRaw：不平滑，直接返回 -1/0/1，用于精确控制（平台跳跃常用）。"],
   "tips":[{"t":"note","c":"GetAxis 平滑适合“驾驶/滑行手感”；GetAxisRaw 干脆适合“格斗/精确走位”。"}]},
  {"h":"实战：控制角色移动","lead":"用轴输入实现移动。",
   "steps":["新建脚本 PlayerMove（挂到带刚体的角色上）：","public float speed = 5f;","void Update() {","float h = Input.GetAxis(\"Horizontal\");","float v = Input.GetAxis(\"Vertical\");","Vector3 move = new Vector3(h, 0, v) * speed * Time.deltaTime;","transform.Translate(move, Space.World);","}","播放：WASD 或方向键控制角色移动。","【转向】让角色朝移动方向转身：if (move != Vector3.zero) transform.rotation = Quaternion.LookRotation(move);","【刚体版】用 rb.velocity 控制：rb.velocity = new Vector3(h * speed, rb.velocity.y, v * speed);（物理更平滑）。","【相对相机】让移动方向相对相机朝向（第 118 课进阶）。","【Debug】打印 h、v 观察平滑值变化。"],
   "tips":[{"t":"success","c":"GetAxis 五秒上手：读轴 → 组成向量 → 乘以速度与 deltaTime。"}]},
 ],
 "errors":[{"err":"GetAxis 没反应？","why":"Input Manager 映射缺失或焦点不在游戏视图","fix":"确认 Input Manager 里有 Horizontal/Vertical 轴；点击 Game 视图再按键盘。"}],
 "exercise":["用 GetAxis 实现四方向移动","打印 h、v 观察平滑变化","把角色旋转朝向移动方向"],
 "summary":"GetAxis 已掌握。下一课学按键检测 GetKey。"},

{"num":112,"title":"键盘按键输入 GetKey 系列","summary":"掌握 GetKey/GetKeyDown/GetKeyUp 检测按键的三个时机，处理各类操作。","keywords":"getkey,getkeydown,getkeyup,键盘,按键,keycode","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解三个按键方法的区别","掌握 KeyCode 枚举","实现按键操作"],
 "intro":"“按一下空格跳”是 GetKeyDown；“按住 Shift 跑”是 GetKey；“松开跳更高”是 GetKeyUp。本课把三种时机讲透。",
 "sections":[
  {"h":"三种按键方法","lead":"时机不同。",
   "steps":["【GetKeyDown】“按下那一刻”触发一次：if (Input.GetKeyDown(KeyCode.Space)) { 跳跃 }","适合：一次性的动作（跳、开枪、开门、暂停）。","【GetKey】“按住期间”每帧都为 true：if (Input.GetKey(KeyCode.LeftShift)) { 加速跑 }","适合：持续状态（跑步、蓄力、连发）。","【GetKeyUp】“松开那一刻”触发一次：if (Input.GetKeyUp(KeyCode.Space)) { 起跳结束 }","适合：松手触发的动作（蓄力释放、大跳）。","【KeyCode 枚举】KeyCode.Space、KeyCode.W、KeyCode.Escape、KeyCode.R 等，几乎覆盖所有键。","【别名】也可用 Input.GetKey(\"space\") 字符串，但 KeyCode 更规范。","【判断任意键】Input.anyKeyDown（任何键按下）；Input.anyKey（按住）。"],
   "tips":[{"t":"note","c":"记住口诀：Down=按下的瞬间、默认=按住期间、Up=松开瞬间。"}]},
  {"h":"实战：跳跃与暂停","lead":"用三种方法实现。",
   "steps":["新建脚本 KeyDemo，挂到角色上：","void Update() {","if (Input.GetKeyDown(KeyCode.Space)) { Debug.Log(\"起跳\"); }","if (Input.GetKey(KeyCode.LeftShift)) { Debug.Log(\"按住加速中\"); }","if (Input.GetKeyUp(KeyCode.Space)) { Debug.Log(\"松手\"); }","if (Input.GetKeyDown(KeyCode.Escape)) { Debug.Log(\"暂停游戏\"); Time.timeScale = 0f; }","if (Input.GetKeyDown(KeyCode.R)) { Time.timeScale = 1f; }","}","播放：按空格、按住 Shift、松开空格、按 Esc 暂停、按 R 恢复。","【注意】GetKeyDown 只在“从没按到按”的一帧为 true，不会重复触发。","【组合键】if (Input.GetKey(KeyCode.LeftControl) && Input.GetKeyDown(KeyCode.C)) { 复制 }","【输入框冲突】UI 有输入框时，打字会触发游戏按键，需用 EventSystem 判断焦点（第 152 课）。"],
   "tips":[{"t":"success","c":"按键三兄弟 + KeyCode 枚举，覆盖所有键盘操作需求。"}]},
 ],
 "errors":[{"err":"按住按键但 GetKeyDown 只触发一次？","why":"GetKeyDown 本来就只触发一次（这是对的）","fix":"需要持续效果用 GetKey，而不是 GetKeyDown。"}],
 "exercise":["用 GetKeyDown 实现跳跃","用 GetKey 实现按住加速","用 GetKeyUp 实现松手释放技能"],
 "summary":"键盘输入已掌握。下一课学鼠标输入。"},

{"num":113,"title":"鼠标输入（位置/点击/滚轮）","summary":"掌握鼠标位置、点击、滚轮、鼠标移动增量，实现瞄准、射击、视角控制。","keywords":"鼠标,鼠标输入,mouseposition,滚轮,mouse delta,点击","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握鼠标位置获取","掌握鼠标按键检测","掌握滚轮与增量"],
 "intro":"射击瞄准、拖拽、缩放视角全靠鼠标。本课把鼠标输入的方方面面讲清楚。",
 "sections":[
  {"h":"鼠标位置与点击","lead":"读位置、读按键。",
   "steps":["【位置】Input.mousePosition：鼠标的屏幕坐标（像素，左下角原点）。","【坐标转换】屏幕坐标 → 世界：Camera.main.ScreenToWorldPoint(...)（配合深度）；屏幕 → 射线：Camera.main.ScreenPointToRay（第 100 课）。","【左键】Input.GetMouseButtonDown(0)：左键按下一瞬；GetMouseButton(0)：按住；GetMouseButtonUp(0)：松开。","【右键】参数 1；【中键】参数 2。","【使用】射击：GetMouseButtonDown(0) 触发。","【看向鼠标】让 2D/俯视角色朝向鼠标位置：先转世界坐标再 LookAt。","【鼠标悬停 UI】事件系统处理（第 10 章 UI）。"],
   "tips":[{"t":"note","c":"GetMouseButton 的参数：0=左键、1=右键、2=中键。"}]},
  {"h":"滚轮与鼠标增量","lead":"缩放手感与视角旋转。",
   "steps":["【滚轮】Input.GetAxis(\"Mouse ScrollWheel\")：滚动返回 0.1/0/-0.1 等增量值。","【相机缩放】把滚轮值加到相机距离：camDistance -= Input.GetAxis(\"Mouse ScrollWheel\") * zoomSpeed; 并 Clamp 限制范围。","【鼠标移动增量】Input.GetAxis(\"Mouse X\")：鼠标水平移动量；Input.GetAxis(\"Mouse Y\")：垂直移动量。","【视角旋转】用 Mouse X 控制水平旋转、Mouse Y 控制俯仰：","float mx = Input.GetAxis(\"Mouse X\");","transform.Rotate(0, mx * sensitivity, 0);","【第一人称视角】用 Mouse X/Y 控制相机旋转（第 118 课详讲）。","【注意】增量基于“帧间鼠标移动”，与分辨率无关，适合视角控制。"],
   "tips":[{"t":"note","c":"鼠标控制视角 = GetAxis(\"Mouse X/Y\") × 灵敏度，是 FPS 的基础。"}]},
 ],
 "errors":[{"err":"鼠标位置转世界坐标不对？","why":"ScreenToWorldPoint 需要 z 值","fix":"转换前先设 mouse.z = 目标深度（如相机距离），或使用 ScreenPointToRay 方案。"}],
 "exercise":["用鼠标左键点击时打印点击物体（射线）","用滚轮缩放相机距离","用 Mouse X/Y 实现基本的相机视角旋转"],
 "summary":"鼠标输入已掌握。下一课学触摸输入。"},

{"num":114,"title":"触摸输入与多点触控","summary":"掌握触摸输入基础与多点触控，为移动端游戏做准备。","keywords":"触摸,触控,touch,多点触控,移动端,手机游戏","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握触摸输入基础","掌握多点触控","理解触摸与鼠标的映射"],
 "intro":"手机游戏用触摸操控。本课学习 Unity 的触摸输入 API（电脑上可用触摸模拟或后续真机测试）。",
 "sections":[
  {"h":"触摸输入基础","lead":"Touch 结构。",
   "steps":["【触摸数量】Input.touchCount：当前屏幕上的触摸点数。","【遍历触摸】for (int i = 0; i < Input.touchCount; i++) { Touch t = Input.GetTouch(i); }","【Touch 属性】t.position（触摸位置）、t.phase（状态）、t.fingerId（手指 ID）、t.deltaTime。","【phase 状态】TouchPhase.Began（刚按下）、Moved（移动中）、Stationary（按住不动）、Ended（抬起）、Canceled（取消）。","【单点点击】if (Input.touchCount == 1 && Input.GetTouch(0).phase == TouchPhase.Began) { 点击处理 }","【坐标】触摸位置 t.position 与鼠标坐标同体系（屏幕坐标），可转世界/射线。","【注意】移动端运行时，Input 会同时报告鼠标（模拟），需注意区分（Input.simulateMouseWithTouches）。"],
   "tips":[{"t":"note","c":"触摸的 phase 类似鼠标的 Down/Hold/Up，按状态机处理。"}]},
  {"h":"多点触控与缩放","lead":"实现双指缩放。",
   "steps":["【检测双指】if (Input.touchCount == 2) { Touch t1 = Input.GetTouch(0); Touch t2 = Input.GetTouch(1); }","【双指距离】Vector2 prev1 = t1.position - t1.deltaPosition; 用上一帧与当前帧的位置差算距离变化。","【缩放实现】记录两指距离变化：","float prevDist = Vector2.Distance(t1.position - t1.deltaPosition, t2.position - t2.deltaPosition);","float currDist = Vector2.Distance(t1.position, t2.position);","float delta = (currDist - prevDist) * 0.01f; // 距离增量","camDistance = Mathf.Clamp(camDistance - delta, min, max);","【双指旋转】同理用两指连线的角度变化控制旋转（进阶）。","【单指拖动】在 Moved 阶段记录增量移动物体。","【测试】电脑上用触摸模拟（较新编辑器支持多点触控模拟）或打包到手机测试（第 285 课）。"],
   "tips":[{"t":"note","c":"双指缩放 = 算两指距离变化 → 换算成缩放量。掌握这个公式，移动端交互就有了。"}]},
 ],
 "errors":[{"err":"触摸没反应？","why":"在电脑上运行没有触摸事件","fix":"电脑上触摸事件通常不会触发；用鼠标模拟或真机测试（打包安卓）。"}],
 "exercise":["实现单指点击检测","实现双指缩放相机","说出 TouchPhase 的几种状态"],
 "summary":"触摸输入已掌握。下一课对比新旧输入系统。"},

{"num":115,"title":"新旧输入系统对比与迁移","summary":"了解旧版 Input Manager 与新 Input System 的差异，决定用哪个。","keywords":"输入系统,input system,新旧对比,迁移,包管理器","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解新旧输入系统区别","知道如何启用新版","掌握选择建议"],
 "intro":"Unity 推出了新一代输入系统（Input System），与旧的 Input Manager 并存。本课帮你搞清怎么选、怎么切换。",
 "sections":[
  {"h":"两套系统对比","lead":"先认清差异。",
   "steps":["【旧版 Input Manager】用 Input.GetAxis/GetKey 等（我们前几课用的）：简单、资料多、开箱即用，多数教程沿用。","【新版 Input System】通过 Package Manager 安装：支持手柄/触摸/键鼠统一抽象、配置化映射、性能更好、代码异步。","【旧版缺点】手柄/多平台支持弱、无法配置复杂映射、虚拟按键少。","【新版缺点】上手曲线陡、API 与旧教程不同、需要额外学习。","【兼容模式】新版提供“Both”模式：同时启用新旧两套（适合学习过渡）。","【选择建议】新手入门阶段用旧版（资料多、简单）；做多平台/专业项目用新版。"],
   "tips":[{"t":"note","c":"本教程以旧版 Input 为主（最通用、资料最全），你完全够用；新版作为进阶了解。"}]},
  {"h":"启用新版与切换","lead":"想用新版怎么办。",
   "steps":["【安装】Package Manager → 搜 Input System → Install（第 43 课装包方法）。","安装后 Unity 会弹窗询问：使用新输入系统？建议选【Yes】或【Both】。","【手动切换】Edit → Project Settings → Player → Active Input Handling：Input Manager (Old) / Input System Package (New) / Both。","【切换影响】切到 New 后，Input.GetAxis 等旧代码会报错；切回 Old 恢复。","【Both 模式】新旧并存：旧代码可跑，新版也能用。","【新版代码示例】（进阶了解）：用 PlayerInput 组件或 InputAction 资产，事件回调处理输入。","【建议】先学完旧版基础，再接触新版。切换前备份项目。"],
   "tips":[{"t":"warn","c":"切换输入系统前保存项目；用 Both 模式最稳妥，避免旧代码报错。"}]},
 ],
 "errors":[{"err":"切到新输入后 Input.GetAxis 报错？","why":"新系统禁用旧 API","fix":"把 Active Input Handling 设为 Both 或 Old；或改用新版 API。"}],
 "exercise":["查看你的项目当前输入处理方式","安装 Input System 包并体验弹窗","切换为 Both 模式理解兼容"],
 "summary":"新旧输入系统已理清。下一课深入新版 Input System。"},

{"num":116,"title":"新版 Input System 配置入门","summary":"掌握新版输入系统的配置：Input Actions 资产、Action Map、绑定与回调。","keywords":"input system,input actions,action map,绑定,回调,playerinput","time":"约 16 分钟","difficulty":"入门",
 "objectives":["理解 Input Actions 结构","掌握创建与绑定","掌握回调写法"],
 "intro":"新版输入系统用“输入动作资产”把“抽象动作”（移动/跳跃）与“具体按键”（WASD/手柄摇杆）解耦。本课入门。",
 "sections":[
  {"h":"Input Actions 资产","lead":"先创建动作资产。",
   "steps":["确认已启用 Input System（第 115 课，建议 Both）。","在 Project 右键 → Create → Input Actions，命名 PlayerControls。","双击打开资产编辑窗口（Input Actions Editor）。","【Action Maps 动作映射】左侧可建多个映射：如“Gameplay”“UI”，分别装不同动作。","【Actions 动作】在映射里建动作：右键 → Add Action，如 Move（Vector2 类型）、Jump（Button 类型）。","【Properties】右侧设置动作类型：Value（连续值，如摇杆）、Button（按钮）、Pass-Through。","【Bindings 绑定】选中动作 → 点 + 号添加绑定：如 Move 绑定 WASD/摇杆（自动有 Keyboard 和 Gamepad 默认模板）。","保存资产（Ctrl+S）。"],
   "tips":[{"t":"note","c":"动作资产把“逻辑动作”与“具体按键”分离：换平台/改键不改代码，只改资产。"}]},
  {"h":"代码中读取输入","lead":"用 PlayerInput 或生成类。",
   "steps":["【方式1 PlayerInput 组件】给对象加 PlayerInput 组件，资产选 PlayerControls，默认行为模式设“Invoke Unity Events”。","在资产编辑器里给动作添加“响应行为”（Response Behavior）：在动作上右键 → Add Binding… 复杂，官方推荐生成 C# 类。","【方式2 生成 C# 类（推荐）】在资产编辑器右上角点【Generate C# Class】，勾选，保存后生成 PlayerControls.cs。","然后在脚本里：","PlayerControls controls;","void Awake() { controls = new PlayerControls(); }","void OnEnable() { controls.Gameplay.Enable(); }","void OnDisable() { controls.Gameplay.Disable(); }","读取移动：Vector2 move = controls.Gameplay.Move.ReadValue<Vector2>();","跳跃事件：controls.Gameplay.Jump.performed += ctx => Jump();","【要点】Enable/Disable 控制映射生效；performed 在按下瞬间回调。","【进阶】还可以用 SetBindingOverride 改键（运行时改键）。"],
   "tips":[{"t":"success","c":"新版输入：动作资产定义“做什么” → 绑定定义“用什么” → C# 生成类读取/回调。"}]},
 ],
 "errors":[{"err":"生成 C# 类按钮找不到？","why":"版本差异或没点开资产编辑器右上角","fix":"在 Input Actions 编辑器右上角（... 菜单）里找 Generate C# Class；或升级包版本。"}],
 "exercise":["创建 PlayerControls 输入资产","配置 Move（Vector2）与 Jump（Button）动作","生成 C# 类并在脚本中读取移动与跳跃"],
 "summary":"新版输入已入门。下一课实现完整的角色移动脚本。"},

{"num":117,"title":"角色移动脚本（WASD + 相机）","summary":"实现面向相机的角色移动：WASD 移动、朝向、刚体控制，标准第三人称移动。","keywords":"角色移动,移动脚本,第三人称,相对相机,刚体移动,朝向","time":"约 16 分钟","difficulty":"入门",
 "objectives":["实现标准移动脚本","实现相对相机移动","实现转向与速度控制"],
 "intro":"几乎所有 3D 游戏都要“控制角色移动”。本课实现一个标准的第三人称移动脚本，可直接复用。",
 "sections":[
  {"h":"基础移动脚本","lead":"读输入、算方向、移动。",
   "steps":["新建脚本 ThirdPersonMove 挂到角色：","public float moveSpeed = 5f;","void Update() {","float h = Input.GetAxis(\"Horizontal\");","float v = Input.GetAxis(\"Vertical\");","Vector3 move = new Vector3(h, 0, v);","move = transform.TransformDirection(move); // 转为世界方向（相对自身）","transform.Translate(move * moveSpeed * Time.deltaTime, Space.World);","}","这是“相对角色自身”的移动（不随相机）。","【刚体版】配合 Rigidbody：rb.velocity = move * moveSpeed;（保持 y 速度），更平滑、碰撞更稳。","【加速/减速】用 Mathf.Lerp 让速度渐进：当前速度向目标速度插值，手感更滑。","【跑步】按住 Shift 时 moveSpeed 翻倍（第 112 课 GetKey）。"],
   "tips":[{"t":"note","c":"先跑通“自身坐标移动”，再升级到“相对相机移动”（下一步）。"}]},
  {"h":"相对相机移动","lead":"按相机方向移动（标准的第三人称）。",
   "steps":["目标：按 W 是“朝相机看的方向”走，而不是“朝世界 Z”。","获取相机的前方/右方（忽略 Y）：","Transform cam = Camera.main.transform;","Vector3 forward = cam.forward; forward.y = 0; forward.Normalize();","Vector3 right = cam.right; right.y = 0; right.Normalize();","Vector3 moveDir = forward * v + right * h;","transform.position += moveDir * moveSpeed * Time.deltaTime;","【说明】先取相机朝向，抹平 Y 轴，得到“水平面上的相机方向”。","【朝向】让角色转向移动方向：if (moveDir.sqrMagnitude > 0.01f) transform.rotation = Quaternion.LookRotation(moveDir);","【完整版】把这段整合进一个脚本，WASD 移动 + 自动转向 + 相机任意旋转都正确。","【注意】相机需先有（第 118-119 课）。"],
   "tips":[{"t":"success","c":"“相对相机移动”是第三人称标准：相机朝前，W 就向前。"}]},
 ],
 "errors":[{"err":"角色斜向移动速度变快？","why":"对角输入时向量长度大于 1","fix":"移动方向向量先归一化：moveDir = moveDir.normalized（或 ClampMagnitude(1)）。"}],
 "exercise":["实现自身坐标移动脚本","升级为相对相机移动","加入移动方向转向与跑步加速"],
 "summary":"角色移动脚本已完成。下一课学第一人称视角控制。"},

{"num":118,"title":"第一人称视角控制（鼠标旋转）","summary":"用鼠标控制相机旋转：水平转身 + 垂直俯仰，实现 FPS 视角。","keywords":"第一人称,fps,视角控制,鼠标旋转,俯仰,抬头低头","time":"约 15 分钟","difficulty":"入门",
 "objectives":["实现鼠标水平旋转","实现鼠标垂直俯仰","限制俯仰范围"],
 "intro":"第一人称游戏的“转头”：鼠标左右转身体、上下转相机。本课实现标准 FPS 视角。",
 "sections":[
  {"h":"水平与垂直旋转","lead":"两个轴各司其职。",
   "steps":["新建脚本 MouseLook，挂到玩家/相机上：","public float sensitivity = 2f;","public float minPitch = -80f; public float maxPitch = 80f;","private float pitch = 0f;","void Update() {","float mx = Input.GetAxis(\"Mouse X\") * sensitivity;","float my = Input.GetAxis(\"Mouse Y\") * sensitivity;","transform.Rotate(0, mx, 0); // 绕 Y 轴水平转身","pitch -= my; // 上下累积（注意方向）","pitch = Mathf.Clamp(pitch, minPitch, maxPitch); // 限制抬头低头","transform.localEulerAngles = new Vector3(pitch, transform.localEulerAngles.y, 0); // 应用俯仰","}","【说明】水平用 Rotate 累积；垂直用单独变量 pitch 累积并 Clamp 防止“翻跟头”。","【挂载】把脚本挂到相机所在的玩家对象（水平转身体 + 相机一起转）。"],
   "tips":[{"t":"note","c":"垂直旋转必须单独累积并 Clamp，否则相机会“倒翻”——这是 FPS 的经典坑。"}]},
  {"h":"锁定鼠标与视角","lead":"让鼠标不出窗口。",
   "steps":["【锁定光标】Cursor.lockState = CursorLockMode.Locked; 隐藏并锁定鼠标在屏幕中央（FPS 标准）。","【显示光标】Cursor.lockState = CursorLockMode.None;（打开菜单/暂停时恢复）。","【可见性】Cursor.visible = false/true。","【Esc 退出锁定】按 Esc 解锁并显示鼠标（再点画面重新锁定）。","【实战整合】","void Update() {","if (Input.GetKeyDown(KeyCode.Escape)) { Cursor.lockState = CursorLockMode.None; Cursor.visible = true; }","if (Input.GetMouseButtonDown(0) && Cursor.lockState != CursorLockMode.Locked) { Cursor.lockState = CursorLockMode.Locked; Cursor.visible = false; }","...旋转代码...","}","【注意】锁定后 GetAxis(\"Mouse X\") 依然有效。","【组合】第一人称移动（第 117 课相对相机）+ 鼠标视角 = 完整 FPS 控制。","【进阶】把相机单独放子对象只做俯仰，身体只做水平（更专业）。"],
   "tips":[{"t":"success","c":"FPS 控制 = 相机锁定 + 鼠标水平转身体 + 垂直俯仰。三件套齐活。"}]},
 ],
 "errors":[{"err":"相机乱转/视角穿地？","why":"垂直旋转没 Clamp 或旋转轴错乱","fix":"垂直用独立 pitch 变量累积并 Clamp；确认只对 Y 用 Rotate。"}],
 "exercise":["实现完整的鼠标视角控制","加入光标锁定与 Esc 解锁","（进阶）身体与相机分离，相机只做俯仰"],
 "summary":"第一人称视角已实现。下一课学第三人称跟随相机。"},

{"num":119,"title":"第三人称跟随相机","summary":"实现第三人称相机：跟随 + 环绕 + 缩放 + 碰撞避让，做出专业跟随效果。","keywords":"第三人称,跟随相机,环绕,相机碰撞,相机缩放,orbital camera","time":"约 16 分钟","difficulty":"入门",
 "objectives":["实现跟随相机","实现鼠标环绕","实现碰撞避让与缩放"],
 "intro":"《马里奥》《原神》类视角：相机跟在角色后上方，鼠标可环绕、滚轮可拉近拉远。本课实现完整的第三人称相机。",
 "sections":[
  {"h":"基础环绕跟随相机","lead":"相机绕着角色转。",
   "steps":["思路：相机 = 围绕目标旋转 + 保持距离 + 看向目标。","新建脚本 ThirdPersonCamera 挂到相机：","public Transform target; // 目标（角色）","public float distance = 5f; public float sensitivity = 3f; public float minY = 10f; public float maxY = 80f;","private float yaw = 0f; private float pitch = 30f;","void LateUpdate() {","yaw += Input.GetAxis(\"Mouse X\") * sensitivity;","pitch -= Input.GetAxis(\"Mouse Y\") * sensitivity;","pitch = Mathf.Clamp(pitch, minY, maxY);","Quaternion rot = Quaternion.Euler(pitch, yaw, 0);","Vector3 pos = target.position - rot * Vector3.forward * distance;","transform.position = pos;","transform.LookAt(target);","}","【LateUpdate】在角色移动完成后更新相机（第 71 课）。","【原理】用 yaw/pitch 拼出旋转，相机放在“目标后方 distance 米”，再看向目标。","播放：鼠标拖拽环绕角色、上下调整俯仰。"],
   "tips":[{"t":"note","c":"第三人称相机公式：目标点 - 旋转 × 前方 × 距离 = 相机位置，再 LookAt 目标。"}]},
  {"h":"缩放与碰撞避让","lead":"让相机更聪明。",
   "steps":["【滚轮缩放】distance -= Input.GetAxis(\"Mouse ScrollWheel\") * 2f; distance = Mathf.Clamp(distance, 2f, 10f);","【平滑】用 Lerp 平滑距离与位置变化，避免生硬。","【碰撞避让】相机与目标之间若有墙，应把相机“拉近”到墙前：","RaycastHit hit;","if (Physics.Linecast(target.position, desiredPos, out hit)) {","Vector3 offset = hit.normal * 0.3f; // 墙前偏移一点点","desiredPos = hit.point + offset;","}","【实现】先算期望位置 desiredPos，再用 Linecast 检测是否被遮挡，遮挡则用命中点。","【平滑过渡】transform.position = Vector3.Lerp(transform.position, desiredPos, 10f * Time.deltaTime);","【注意】碰撞避让能避免“相机穿墙看到黑屏”。","【进阶】相机插值延迟跟随、跟随目标点放头顶等。"],
   "tips":[{"t":"success","c":"完整第三人称相机 = 环绕旋转 + 滚轮缩放 + Linecast 防穿墙。照着写即可用。"}]},
 ],
 "errors":[{"err":"相机穿墙/黑屏？","why":"没做碰撞避让","fix":"用 Linecast 检测遮挡并拉近相机位置。"}],
 "exercise":["实现基础环绕跟随相机","加滚轮缩放与平滑","加 Linecast 碰撞避让"],
 "summary":"第三人称相机已完成。下一课学跳跃与重力模拟。"},

{"num":120,"title":"跳跃与重力模拟（角色控制器）","summary":"实现可靠的跳跃：地面检测、跳跃力、重力处理、防止无限跳跃。","keywords":"跳跃,jump,地面检测,重力,防止无限跳,isgrounded","time":"约 15 分钟","difficulty":"入门",
 "objectives":["实现地面检测","实现跳跃","处理下落与防止连跳"],
 "intro":"“跳起来、落回地面”看似简单，但地面检测、防连跳有无数坑。本课给出可靠方案。",
 "sections":[
  {"h":"地面检测","lead":"判断“脚是否在地面上”。",
   "steps":["【方式1 射线检测】从角色脚下向下发一条短射线：","public float groundCheckDistance = 0.2f;","bool IsGrounded() { return Physics.Raycast(transform.position, Vector3.down, groundCheckDistance); }","【方式2 球形检测】OverlapSphere 更稳（对地面不平）：Physics.CheckSphere(footPos, radius, groundMask)。","【方式3 触发器脚】角色底部放一个触发器子物体，OnTriggerStay 时置 grounded=true（经典方案）。","【注意】射线起点应放在“脚底”，距离略大于接触范围。","【LayerMask】只检测地面层（第 99 课），避免把敌人当地面。","【踩多个地面】检测结果每帧更新，落地的瞬间 grounded 变 true。"],
   "tips":[{"t":"note","c":"地面检测是跳跃的“开关”：只有 grounded 为 true 时才允许起跳，防无限跳。"}]},
  {"h":"跳跃与重力实现","lead":"用刚体实现。",
   "steps":["给角色加 Rigidbody（Use Gravity 开）、地面有碰撞体。","新建脚本 JumpController 挂角色：","public float jumpForce = 8f; public float groundDistance = 0.15f;","Rigidbody rb;","void Awake() { rb = GetComponent<Rigidbody>(); }","void Update() {","bool grounded = Physics.Raycast(transform.position, Vector3.down, groundDistance);","if (Input.GetKeyDown(KeyCode.Space) && grounded) {","rb.velocity = new Vector3(rb.velocity.x, 0f, rb.velocity.z); // 先清空垂直速度","rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);","}","}","【说明】跳跃前把 y 速度清零，防止“上抛+残留速度”叠加导致跳太高。","【重力】刚体 Use Gravity 自动处理下落。","【可调跳高】跳跃力根据手感调（8 左右较合理）。","【二段跳】（进阶）设 jumpsRemaining 计数，落地重置。","【Buffer/Coyote】（进阶）跳跃缓冲与土狼时间提升手感。"],
   "tips":[{"t":"success","c":"可靠跳跃 = 地面检测（射线/球）+ 清空 y 速度 + Impulse 冲量。"}]},
 ],
 "errors":[{"err":"跳不起来或跳太低？","why":"jumpForce 太小、地面检测距离不对、或 y 速度没清零","fix":"调大 jumpForce；检查射线是否检测到地面；跳跃前清空 rb.velocity.y。"}],
 "exercise":["实现带地面检测的跳跃","加入防无限跳逻辑","（进阶）实现二段跳"],
 "summary":"跳跃与重力已实现。下一课学 CharacterController 角色控制器。"},

{"num":121,"title":"CharacterController 角色控制器","summary":"掌握 CharacterController：不用刚体的角色移动方案，斜坡、台阶更稳定。","keywords":"charactercontroller,角色控制器,move,issloped,斜坡,台阶","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解 CharacterController 特点","掌握 Move 移动","实现重力与跳跃"],
 "intro":"CharacterController 是 Unity 专门为“角色”设计的控制器：不参与物理、斜坡台阶稳定、不会乱撞。很多游戏用它做角色。",
 "sections":[
  {"h":"CharacterController 基础","lead":"“人形胶囊移动器”。",
   "steps":["给角色添加 CharacterController 组件（会自动去掉 Rigidbody 需求）。","它自带一个胶囊体（Height/Radius 可调），负责“碰撞与阻挡”但不参与物理力。","【核心方法 Move】cc.Move(位移向量); 每帧调用，传入本帧位移（含 deltaTime）。","【简单移动】","CharacterController cc = GetComponent<CharacterController>();","Vector3 move = new Vector3(h, 0, v) * speed * Time.deltaTime;","cc.Move(move);","【区别】Move 自动处理碰撞（撞墙停下、上下坡）。","【SimpleMove】（旧）自动乘速度与 deltaTime，不能控制 Y。","【isGrounded 属性】cc.isGrounded 直接判断是否在地面，无需自己检测！"],
   "tips":[{"t":"note","c":"CharacterController 的 isGrounded 内置，省去地面检测代码，这是它的一大优点。"}]},
  {"h":"重力与跳跃（CC 版）","lead":"手动模拟重力。",
   "steps":["CC 不自动受重力，需要自己累积垂直速度：","private float verticalVel = 0f;","private float gravity = -9.81f;","void Update() {","if (cc.isGrounded && verticalVel < 0) { verticalVel = -1f; } // 贴地","if (Input.GetKeyDown(KeyCode.Space) && cc.isGrounded) { verticalVel = 8f; }","verticalVel += gravity * Time.deltaTime;","Vector3 move = new Vector3(h, verticalVel, v) * Time.deltaTime;","cc.Move(move);","}","【说明】垂直速度持续加重力，落地归零。","【对比】CC 方案适合“精确控制型”角色；刚体适合“物理交互型”物体。","【优点】CC 不会把角色撞飞、不会穿透斜坡、上下坡平滑。","【注意】CC 与刚体混用会互相干扰，选一种方案。"],
   "tips":[{"t":"success","c":"CharacterController 方案 = Move 移动 + 手动重力 + isGrounded 跳跃，是“手感型”角色的首选。"}]},
 ],
 "errors":[{"err":"CC 角色穿地/抖动？","why":"重力累积与地面检测冲突","fix":"isGrounded 且 verticalVel<0 时强制贴地（verticalVel=-1）；Move 在 Update 里调用。"}],
 "exercise":["用 CharacterController 实现移动","实现手动重力与跳跃","对比 CC 与刚体移动的手感差异"],
 "summary":"CharacterController 已掌握。下一课让输入与动画联动。"},

{"num":122,"title":"输入与动画联动","summary":"把输入值转化为动画参数，让角色“走路跑步待机”动画随输入切换。","keywords":"输入动画联动,animator参数,移动动画,动画切换,blend","time":"约 14 分钟","difficulty":"入门",
 "objectives":["把输入映射为动画参数","控制动画状态切换","实现平滑动画过渡"],
 "intro":"角色按 WASD 移动时，播放走路动画；停下播放待机。本课把输入与动画系统接通（动画系统第 9 章详讲，本课先用基础）。",
 "sections":[
  {"h":"准备动画参数","lead":"在 Animator 里设参数。",
   "steps":["【前提】角色有 Animator 组件 + 动画控制器（第 130 课）；本课假设已有 Idle/Walk/Run 状态。","打开动画控制器（Animator Controller），在【参数 Parameters】面板添加：","Speed（Float 类型）：移动速度。","IsMoving（Bool 类型）：是否在移动。","【状态机】确保 Idle→Walk/Run 的过渡条件：Speed 大于阈值时切换到移动状态。","设置过渡（Transition）的 Has Exit Time 取消、Transition Duration 适当（0.1-0.2 平滑过渡）。"],
   "tips":[{"t":"note","c":"动画参数是把“输入数据”传给“动画系统”的桥梁。"}]},
  {"h":"代码驱动动画","lead":"把输入写成参数。",
   "steps":["在角色移动脚本里加：","private Animator anim;","void Awake() { anim = GetComponent<Animator>(); }","void Update() {","float h = Input.GetAxis(\"Horizontal\");","float v = Input.GetAxis(\"Vertical\");","Vector3 move = new Vector3(h, 0, v);","float speed = move.magnitude; // 输入速度（0~1）","anim.SetFloat(\"Speed\", speed);","anim.SetBool(\"IsMoving\", speed > 0.1f);","...移动逻辑...","}","【SetFloat/SetBool】把值写入 Animator 参数，状态机自动切换动画。","【平滑】SetFloat 的第三个参数（dampTime）可平滑过渡：anim.SetFloat(\"Speed\", speed, 0.1f, Time.deltaTime);","【朝向】移动时角色转向（LookRotation），动画与朝向同步。","【跑步】按住 Shift 时 speed 更大，可触发 Run 状态（阈值判断）。","播放测试：按 WASD 走路/跑步，松开待机。"],
   "tips":[{"t":"success","c":"核心一行：anim.SetFloat(\"Speed\", 输入速度)。动画自动“看脸色”切换。"}]},
 ],
 "errors":[{"err":"动画不切换？","why":"参数名不一致、或过渡条件没设置","fix":"确认代码里的参数名与 Animator 参数完全一致；确认过渡条件配置正确。"}],
 "exercise":["在 Animator 添加 Speed/IsMoving 参数","用代码设置参数驱动动画切换","加平滑过渡让切换更自然"],
 "summary":"输入与动画联动已实现。下一课学 UI 按钮点击响应。"},

{"num":123,"title":"UI 按钮点击响应（输入层）","summary":"掌握 UI 按钮的点击事件：OnClick、监听器、代码绑定，实现界面操作。","keywords":"ui按钮,onclick,按钮点击,addlistener,点击事件","time":"约 14 分钟","difficulty":"入门",
 "objectives":["创建 UI 按钮","绑定点击事件","实现界面操作"],
 "intro":"游戏里的“开始游戏”“设置”“继续”按钮，点击后执行逻辑。本课实现 UI 点击响应（UI 系统第 10 章详讲）。",
 "sections":[
  {"h":"创建 UI 按钮","lead":"三步建按钮。",
   "steps":["在 Hierarchy 右键 → UI → Button - TextMeshPro（推荐，中文支持好）。","会自动创建：Canvas（画布）+ EventSystem（事件系统）+ 按钮子物体（文字）。","选中按钮，右侧 Inspector 可见：Image（背景）、Button 组件、TextMeshPro（文字）。","在 Button 组件的【On Click ()】列表下方点【+】添加一个监听项。","把目标对象拖到“None (Object)”槽，在下拉选“函数”（如 GameObject → SetActive 或脚本方法）。","这样点击按钮就会调用指定对象的方法。","修改按钮文字：选中子物体 TextMeshPro，改 Text 内容为“开始游戏”。"],
   "tips":[{"t":"note","c":"EventSystem 是 UI 事件的基础（鼠标点击 UI 都靠它），别删。"}]},
  {"h":"代码绑定点击事件","lead":"更灵活的方式。",
   "steps":["创建脚本 UIManager：","public void StartGame() { Debug.Log(\"开始游戏！\"); SceneManager.LoadScene(\"Level1\"); }","public void QuitGame() { Debug.Log(\"退出游戏\"); Application.Quit(); }","【方式1 Inspector 拖】把挂 UIManager 的对象拖到按钮 On Click 槽，函数选 UIManager.StartGame。","【方式2 代码绑定】在脚本里用 AddListener：","using UnityEngine.UI;","Button startBtn;","void Awake() { startBtn = GameObject.Find(\"StartButton\").GetComponent<Button>(); startBtn.onClick.AddListener(StartGame); }","public void StartGame() { ... }","【推荐】Inspector 拖拽配置直观；代码绑定灵活（可动态生成按钮）。","【参数版本】onClick.AddListener(delegate { StartGame(levelName); }); 可传参。","【注意】按钮被 UI 遮挡时点击无效：检查 Canvas 层级与 Raycast Target。"],
   "tips":[{"t":"success","c":"按钮点击 = Button.onClick + 方法。Inspector 拖或代码 AddListener 二选一。"}]},
 ],
 "errors":[{"err":"点击按钮没反应？","why":"EventSystem 缺失、按钮被遮挡、或 Canvas 无 Graphic Raycaster","fix":"确认场景有 EventSystem；检查 UI 层级与遮挡；确认 Canvas 有 Graphic Raycaster 组件。"}],
 "exercise":["创建“开始游戏”按钮","用 Inspector 拖拽绑定一个方法","用代码 AddListener 绑定一个方法"],
 "summary":"UI 按钮响应已掌握。下一课学自定义按键与键位映射。"},

{"num":124,"title":"自定义按键与键位映射","summary":"用 Input Manager 自定义按键映射，或代码实现“改键”，提升操作自由度。","keywords":"自定义按键,键位映射,input manager,改键,按键设置","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解 Input Manager 映射","掌握改键方法","实现运行时改键"],
 "intro":"“玩家想改按键”是常见需求。本课讲清楚 Unity 按键映射的两种改法：配置文件改 & 代码改。",
 "sections":[
  {"h":"Input Manager 配置改键","lead":"在编辑器里改默认映射。",
   "steps":["菜单 Edit → Project Settings → Input Manager（旧版输入）。","展开 Axes 列表，能看到所有轴（Horizontal、Vertical、Jump 等）。","选一个轴（如 Jump）：展开它的属性。","【Positive Button】主键（如 “space”）；【Alt Positive Button】备用键。","【Keys 写法】小写键名：space、w、a、s、d、left shift、mouse 0 等。","把 Jump 的 Positive Button 改成 “j”：以后按 J 也能跳。","【新建轴】点列表下方 “+” 添加自定义轴（如 Fire），绑定鼠标左键。","【注意】改配置只影响本项目，换项目需重设。"],
   "tips":[{"t":"note","c":"Input Manager 是“策划配键”的入口，改一次全项目生效。"}]},
  {"h":"运行时改键（代码）","lead":"让玩家在游戏里改键。",
   "steps":["思路：不用硬编码 KeyCode，改用“可配置的键名”字段。","方案1：字段存 KeyCode：public KeyCode jumpKey = KeyCode.Space; 判断用 GetKeyDown(jumpKey)；改键 = 改字段值（可在设置界面让玩家选）。","方案2：用一个 Dictionary 存键：Dictionary<string, KeyCode> keyMap; keyMap[\"Jump\"] = KeyCode.Space; 统一查表。","方案3：新版 Input System 用 SetBindingOverride 改绑定（进阶）。","【改键 UI】做一个设置界面：玩家点击“改跳跃键”按钮 → 进入“等待按键”状态 → 按下任意键 → 把 KeyCode 存进 keyMap 并保存到 PlayerPrefs（第 232 课）。","【保存】PlayerPrefs.SetInt(\"JumpKey\", (int)keyMap[\"Jump\"])；启动时读取。","【注意】按键冲突检测：避免两个动作绑定同一键。","【推荐】小项目用“字段存 KeyCode + PlayerPrefs 保存”最实用。"],
   "tips":[{"t":"success","c":"改键三要素：可配置字段/字典 + 按键选择 UI + PlayerPrefs 持久化。"}]},
 ],
 "errors":[{"err":"改键后没生效？","why":"判断里还是硬编码 KeyCode","fix":"把判断改成读取可配置键：Input.GetKeyDown(jumpKey)。"}],
 "exercise":["在 Input Manager 里改一个键位并测试","用 KeyCode 字段实现可改键","把改键保存到 PlayerPrefs"],
 "summary":"自定义按键已掌握。下一课综合练习：场景漫游。"},

{"num":125,"title":"综合练习：3D 场景漫游","summary":"综合运用输入、移动、视角、跳跃，做一个可自由探索的 3D 漫游体验。","keywords":"综合练习,场景漫游,探索,第一人称,移动视角","time":"约 25 分钟","difficulty":"入门",
 "objectives":["综合运用第 8 章全部知识","完成可操作的第一人称漫游","体验完整交互闭环"],
 "intro":"把移动、视角、跳跃组合成一个“第一人称漫游”，在一个小场景里自由探索。输入章毕业项目！",
 "sections":[
  {"h":"搭建漫游场景","lead":"先有可逛的世界。",
   "steps":["新建场景 Roam。","【地面】大 Plane 作为地面，赋木色材质。","【障碍】放几个 Cube/Sphere/圆柱作为“地标”，摆在不同位置与高度。","【高台】放几个高低错落的平台（Cube），方便测试跳跃。","【环境】加几盏点光源/方向光，让场景明亮。","【天空盒】设置 Default-Skybox（第 29 课）。","【玩家起点】一个空对象命名 PlayerStart 放 (0, 1, 0)。"],
   "tips":[{"t":"note","c":"场景越丰富，漫游越有感觉，先简单后加料。"}]},
  {"h":"编写漫游控制","lead":"第一人称 + 跳跃。",
   "steps":["创建玩家：空对象 Player（胶囊体更好看，Scale (0.8,1.8,0.8)），挂 Rigidbody（或 CharacterController）。","给玩家挂两个脚本：","① MouseLook（第 118 课）：鼠标水平+垂直视角，Cursor 锁定。","② FirstPersonMove：","float h = Input.GetAxis(\"Horizontal\"); float v = Input.GetAxis(\"Vertical\");","Vector3 dir = (transform.forward * v + transform.right * h).normalized;","GetComponent<Rigidbody>().velocity = new Vector3(dir.x * speed, rb.velocity.y, dir.z * speed);","③ 跳跃：grounded 时空格 AddForce Impulse（第 120 课）。","把相机作为玩家的子物体，放在 (0,1.6,0)（人眼高度），视角旋转脚本控制相机或玩家。","【注意】水平旋转放玩家（身体），俯仰放相机（子物体）更专业。","播放：WASD 行走、鼠标转头、空格跳跃，探索整个场景！"],
   "tips":[{"t":"success","c":"第一人称漫游 = 刚体移动 + 鼠标视角 + 跳跃 + 碰撞。四件套齐活。"}]},
  {"h":"打磨与收尾","lead":"提升体验。",
   "steps":["【速度手感】调 speed（4-6 合适），加跑步（Shift ×1.8）。","【跳跃手感】jumpForce 8-10，跳上高台验证。","【相机平滑】相机子物体 + LateUpdate 微平滑。","【音效】（可选）加脚步音效（第 11 章）。","【完成标记】做一个“探索完成”触发区（Is Trigger），走进触发打印“恭喜探索完成！”（第 96 课）。","检查 Console 无报错，保存。","展示给你的朋友：这是你亲手做的可玩漫游！"],
   "tips":[{"t":"note","c":"输入章完结！你已掌握让玩家“操控”游戏的完整能力。下一章进入动画系统。"}]},
 ],
 "errors":[{"err":"视角乱转或角色乱飘？","why":"相机与身体旋转职责没分清","fix":"水平旋转放玩家，俯仰放相机子物体；垂直角度 Clamp。"}],
 "exercise":["完成第一人称漫游（移动+视角+跳跃）","加跑步与触发区","（进阶）加脚步音效与场景传送门"],
 "summary":"场景漫游完成！输入章毕业。下一章进入动画系统，让角色“活起来”。"},
]
